Spiral Matrix:
def solve(matrix):
    if not matrix: return []
    top, bot, left, right = 0, len(matrix) - 1, 0, len(matrix[0]) - 1
    res = []
    while top <= bot and left <= right:
        for j in range(left, right + 1): res.append(matrix[top][j])
        top += 1
        for i in range(top, bot + 1): res.append(matrix[i][right])
        right -= 1
        if top <= bot:
            for j in range(right, left - 1, -1): res.append(matrix[bot][j])
            bot -= 1
        if left <= right:
            for i in range(bot, top - 1, -1): res.append(matrix[i][left])
            left += 1
    return res

Set Matrix Zeroes:
def solve(matrix):
    if not matrix: return matrix
    m, n = len(matrix), len(matrix[0])
    row0 = any(matrix[0][j] == 0 for j in range(n))
    col0 = any(matrix[i][0] == 0 for i in range(m))
    for i in range(1, m):
        for j in range(1, n):
            if matrix[i][j] == 0:
                matrix[i][0] = matrix[0][j] = 0
    for i in range(1, m):
        for j in range(1, n):
            if matrix[i][0] == 0 or matrix[0][j] == 0:
                matrix[i][j] = 0
    if row0:
        for j in range(n): matrix[0][j] = 0
    if col0:
        for i in range(m): matrix[i][0] = 0
    return matrix

