Longest Palindromic Substring:
def solve(s):
    if not s: return ''
    start, end = 0, 0
    def expand(l, r):
        while l >= 0 and r < len(s) and s[l] == s[r]:
            l -= 1; r += 1
        return r - l - 1
    for i in range(len(s)):
        l1 = expand(i, i)
        l2 = expand(i, i + 1)
        L = max(l1, l2)
        if L > end - start:
            start = i - (L - 1) // 2
            end = i + L // 2
    return s[start:end + 1]

